import type { BenchmarkTask, MockSettings } from "./types";

export const MOCK_PROVIDER_ID = "mock-deterministic-v1";
export const MOCK_NOTICE =
  "Generated by the deterministic MOCK provider. Not real LLM behaviour; failures and omissions are injected by configured rates.";

/** FNV-1a hash -> 32-bit seed */
export function hashSeed(...parts: (string | number)[]) {
  let h = 0x811c9dc5;
  for (const ch of parts.join("|")) {
    h ^= ch.charCodeAt(0);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}
/** mulberry32 PRNG — deterministic for a given seed */
export function rng(seed: number) {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export class ModelRequestError extends Error {
  category = "model_request_failure";
}
export class ToolError extends Error {
  category = "tool_failure";
}
export class TimeoutError extends Error {
  category = "timeout";
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const COMPLEXITY_MULT: Record<string, number> = { low: 1, medium: 2, high: 3 };

export interface EmployeeAssignment {
  task: BenchmarkTask;
  agent_id: string;
  facts: string[];
  fields: string[];
}

export interface MockCallResult {
  raw: string;
  est_tokens_in: number;
  est_tokens_out: number;
}

/**
 * Deterministic mock "LLM". The same (seed, task, agent, attempt) always
 * yields the same output and the same injected failure.
 */
export class MockProvider {
  constructor(
    private s: MockSettings,
    private seed: number,
  ) {}

  rand(...parts: (string | number)[]) {
    return rng(hashSeed(this.seed, ...parts));
  }

  async employeeCall(a: EmployeeAssignment, attempt: number, timeoutMs: number): Promise<MockCallResult> {
    const r = this.rand("emp", a.task.task_key, a.agent_id, attempt);
    const mult = COMPLEXITY_MULT[a.task.complexity] ?? 1;
    let delay = this.s.employeeBaseDelayMs + this.s.complexityDelayMs * mult * (0.5 + r());
    const willTimeout = r() < this.s.timeoutRate;
    if (willTimeout) delay = timeoutMs + 5;
    const fail = r() < this.s.modelFailureRate;
    const invalid = r() < this.s.invalidJsonRate;
    await Promise.race([
      sleep(Math.min(delay, timeoutMs + 5)),
    ]);
    if (delay > timeoutMs) throw new TimeoutError(`mock employee exceeded timeout ${timeoutMs}ms`);
    if (fail) throw new ModelRequestError("mock injected model request failure (HTTP 503)");
    const findings = a.facts.filter(() => r() >= this.s.employeeOmissionRate);
    const fields: Record<string, string> = {};
    for (const f of a.fields) fields[f] = `[mock] value for ${f} from ${a.agent_id}`;
    const out = {
      task_id: a.task.task_key,
      agent_id: a.agent_id,
      status: "success",
      findings,
      fields,
      evidence: findings.map((f, i) => ({ claim: f, source: `mock-doc:${a.task.task_key}:${a.agent_id}:${i}` })),
      uncertainties: a.task.conflicting ? [`Source for ${a.agent_id} conflicts with other sources`] : [],
      warnings: [],
      error_details: null,
      generated_by: MOCK_PROVIDER_ID,
    };
    const raw = invalid ? JSON.stringify(out).slice(0, -7) : JSON.stringify(out);
    const inTok = Math.ceil((a.task.description.length + a.facts.join(" ").length) / 4);
    return { raw, est_tokens_in: inTok, est_tokens_out: Math.ceil(raw.length / 4) };
  }

  async toolCall(taskKey: string, agentId: string, attempt: number) {
    const r = this.rand("tool", taskKey, agentId, attempt);
    await sleep(5 + r() * 10);
    if (r() < this.s.toolFailureRate) throw new ToolError("mock.lookup tool returned error");
    return { tool: "mock.lookup", ok: true };
  }

  /** Manager aggregation model-call delay grows with number of inputs. */
  async managerCall(taskKey: string, inputCount: number, label: string) {
    const r = this.rand("mgr", taskKey, label);
    await sleep(this.s.managerBaseDelayMs + this.s.managerPerInputDelayMs * inputCount * (0.8 + 0.4 * r()));
    return r;
  }
}
